import { readFileSync, writeFileSync } from 'node:fs';

const tokens = JSON.parse(readFileSync('src/shared/theme/tokens.json', 'utf8'));
const file = 'src/shared/theme/uniwind-theme.css';
const kebab = (key) => key.replace(/[A-Z]/g, (char) => '-' + char.toLowerCase());
const flat = (value, keys = []) =>
  Object.entries(value).flatMap(([key, entry]) =>
    typeof entry === 'string'
      ? [[kebab([...keys, key].join('-')), entry]]
      : flat(entry, [...keys, key]),
  );
const light = flat(tokens.color);
const dark = flat(tokens.darkColor);
const expected = [
  '/* Auto-generated from tokens.json: node scripts/generate-uniwind-theme.mjs --write */',
  '/* Do not edit this file manually. JSON tokens remain the brand source of truth. */',
  '@theme inline {',
  '  --color-brand-mark: var(--brand-mark);',
  ...light.map(([name]) => '  --color-' + name + ': var(--' + name + ');'),
  '  --font-ui-regular: "' + tokens.font.regular + '";',
  '  --font-ui-medium: "' + tokens.font.medium + '";',
  '  --font-ui-semibold: "' + tokens.font.semibold + '";',
  '  --font-ui-bold: "' + tokens.font.bold + '";',
  ...Object.entries(tokens.typography).flatMap(([key, value]) => [
    '  --text-type-' + key + ': ' + value.fontSize + 'px;',
    '  --text-type-' + key + '--line-height: ' + value.lineHeight + 'px;',
  ]),
  ...Object.entries(tokens.radius).map(
    ([key, value]) => '  --radius-' + kebab(key) + ': ' + value + 'px;',
  ),
  ...Object.entries(tokens.size).map(
    ([key, value]) => '  --spacing-' + kebab(key) + ': ' + value + 'px;',
  ),
  '}',
  '',
  '@theme {',
  '  --font-normal: "' + tokens.font.regular + '";',
  '  --font-medium: "' + tokens.font.medium + '";',
  '  --font-semibold: "' + tokens.font.semibold + '";',
  '  --font-bold: "' + tokens.font.bold + '";',
  '}',
  '',
  '@layer theme {',
  '  :root {',
  '    @variant light {',
  '      --brand-mark: ' + tokens.brand.mark + ';',
  ...light.map(([name, value]) => '      --' + name + ': ' + value + ';'),
  '      --background: ' + tokens.color.surface.canvas + ';',
  '      --foreground: ' + tokens.color.text.primary + ';',
  '      --surface: ' + tokens.color.surface.default + ';',
  '      --surface-foreground: ' + tokens.color.text.primary + ';',
  '      --accent: ' + tokens.color.action.primary + ';',
  '      --accent-foreground: ' + tokens.color.text.onAction + ';',
  '    }',
  '    @variant dark {',
  '      --brand-mark: ' + tokens.brand.mark + ';',
  ...dark.map(([name, value]) => '      --' + name + ': ' + value + ';'),
  '      --background: ' + tokens.darkColor.surface.canvas + ';',
  '      --foreground: ' + tokens.darkColor.text.primary + ';',
  '      --surface: ' + tokens.darkColor.surface.default + ';',
  '      --surface-foreground: ' + tokens.darkColor.text.primary + ';',
  '      --accent: ' + tokens.darkColor.action.primary + ';',
  '      --accent-foreground: ' + tokens.darkColor.text.onAction + ';',
  '    }',
  '  }',
  '}',
  '',
].join('\n');

if (process.argv.includes('--write')) {
  writeFileSync(file, expected);
  process.stdout.write('Uniwind theme regenerated from UberTib tokens.\n');
} else if (process.argv.includes('--check')) {
  if (readFileSync(file, 'utf8') !== expected)
    throw new Error(
      'Uniwind theme is out of sync. Run node scripts/generate-uniwind-theme.mjs --write',
    );
  process.stdout.write('Uniwind CSS theme matches UberTib tokens.\n');
} else {
  process.stdout.write('Use --write or --check.\n');
}
